def solve():
    memo = {}

    def get_moves(boards, player):
        boards = tuple(sorted([b for b in boards if b > 0]))
        if not boards:
            return 0

        state = (boards, player)
        if state in memo:
            return memo[state]

        if player == 0: # Alice wants to minimize moves
            res = float('inf')
            possible_move = False
            for i, b in enumerate(boards):
                if b >= 2:
                    possible_move = True
                    for j in range(1, b):
                        new_boards = list(boards)
                        new_boards.pop(i)
                        new_boards.append(j - 1)
                        new_boards.append(b - j - 1)
                        res = min(res, 1 + get_moves(tuple(new_boards), 1))
            if not possible_move:
                res = 0
        else: # Bob wants to maximize moves
            res = float('-inf')
            possible_move = False
            for i, b in enumerate(boards):
                if b >= 2:
                    possible_move = True
                    for j in range(1, b):
                        new_boards = list(boards)
                        new_boards.pop(i)
                        new_boards.append(j - 1)
                        new_boards.append(b - j - 1)
                        res = max(res, 1 + get_moves(tuple(new_boards), 0))
            if not possible_move:
                res = 0

        memo[state] = res
        return res

    for n in range(1, 15):
        moves = get_moves((n,), 0)
        print(f"n={n}, moves={moves}, uncovered={n - 2*moves}")

